    #[test]
    fn set_plr_knowledge_defaults_omitted_remove_to_false() {
        let mut player = PlayerState::default();
        player.id = 7;
        let definitions = HashMap::from([(
            "BRIK".to_string(),
            DefinitionMetadata {
                name: String::new(),
                portrait_names: Vec::new(),
                category: 0x1,
                border_bound: 0,
                contact_function_calls: false,
                blit_mode: 0,
                ocf_base: 0,
                crew_member: false,
                crew_member_value: 0,
                silent_commands: false,
                vehicle_control: 0,
                action_library: ActionLibrary::default().into(),
                control_transfer_callback: None,
                action_graphics: HashMap::new(),
                value: 0,
                allow_picture_stack: 0,
                mass: 0,
                no_component_mass: false,
                constructable: false,
                shape: None,
                placement: 0,
                growth: 0,
                construction_offset: 0,
                basement: 0,
                physical: PhysicalInfo::default(),
                components: Vec::new(),
                collection_limit: 0,
                grab_put_get: 0,
                line_connect: 0,
                clonk_name_newlines: None,
                stretch_growth: false,
                rotateable: 0,
                line: 0,
                vertices: Vec::new(),
                contact_density: None,
                fire: DefinitionFireMetadata::default(),
            },
        )]);
        let world = HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            None,
            definitions,
            Vec::new(),
            HashMap::from([(7, player)]),
            HashMap::new(),
            1,
            false,
        );
        // Parse_Params pads omitted parameters with nil, whose bool
        // conversion is false (C4AulParse.cpp:2342-2344; C4Value.h:325-330).
        // Dragon Rock's InitializePlayer relies on this two-argument grant.
        let args = [Value::Int(7), Value::C4Id("BRIK".into())];
        let (result, outcome) =
            with_effect_context(None, &[], world, 1, || set_plr_knowledge(&args));

        assert_eq!(result.expect("SetPlrKnowledge succeeds"), Value::Bool(true));
        assert_eq!(outcome.player_commands.len(), 1);
        match &outcome.player_commands[0] {
            PlayerCommand::GrantKnowledge {
                player_id,
                definition_id,
            } => {
                assert_eq!(*player_id, 7);
                assert_eq!(definition_id, "BRIK");
            }
            other => panic!("unexpected player command: {other:?}"),
        }
    }

